<script setup lang="ts">
import { COPY } from '../copy';
import type { WrongBook } from '../types';
const props=defineProps<{wrong:WrongBook;sort:'count'|'recent';today:string;busy:boolean}>();
defineEmits<{sort:[value:'count'|'recent'];remove:[id:number];practice:[];home:[]}>();
function relative(iso:string){const day=new Date(new Date(iso).getTime()+28800000).toISOString().slice(0,10);const n=Math.max(0,Math.round((Date.parse(props.today)-Date.parse(day))/86400000));return n===0?'今天':n===1?'昨天':`${n} 天前`;}
</script>
<template><main class="page"><div class="headrow"><div><h1>错词本 {{ wrong.total }} 个</h1><p v-if="wrong.total" class="muted">其中 {{ wrong.practicedTwiceThisWeek }} 个本周已练对 2 次。{{ COPY.wrongRule }}</p></div><div v-if="wrong.total" class="actions"><div class="seg"><button :class="{on:sort==='count'}" :disabled="busy" @click="$emit('sort','count')">{{ COPY.wrongSortCount }}</button><button :class="{on:sort==='recent'}" :disabled="busy" @click="$emit('sort','recent')">{{ COPY.wrongSortRecent }}</button></div><button v-if="wrong.total" class="btn primary" :disabled="busy" @click="$emit('practice')">{{ COPY.practice(Math.min(10,wrong.total)) }}</button></div></div>
<div v-if="wrong.total" class="wlist"><div v-for="w in wrong.items" :key="w.word_id" class="witem"><div class="w">{{ w.headword }}<small v-if="w.phonetic">{{ w.phonetic }}</small></div><div class="m"><div>{{ (w.meaning_zh??'').split('\n')[0] }}</div><div class="qt"><span v-for="(n,q) in w.fails" :key="q">{{ COPY.qtypes[q] }} ×{{ n }}</span></div></div><div class="dots"><i v-for="n in 3" :key="n" :class="{on:n<=w.correct_days}"></i><span>{{ w.correct_days }}/3 天</span></div><div class="count">{{ w.wrong_count }} 次<small>{{ relative(w.last_wrong_at) }}</small></div><button class="iconbtn" :disabled="busy" :aria-label="`移出 ${w.headword}`" @click="$emit('remove',w.word_id)">移出</button></div></div>
<section v-else class="panel empty"><svg viewBox="0 0 120 96" fill="none" aria-hidden="true"><rect x="14" y="14" width="44" height="66" rx="6" fill="var(--primary-soft)"/><rect x="62" y="14" width="44" height="66" rx="6" fill="var(--primary-soft)"/><path d="M60 18v62" stroke="var(--wave)" stroke-width="2"/><path d="M24 32h26M24 42h20M72 32h24M72 42h18" stroke="var(--wave)" stroke-width="3" stroke-linecap="round"/><circle cx="92" cy="68" r="16" fill="var(--ok)"/><path d="M85 68l5 5 9-10" stroke="var(--surface)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg><h2>{{ COPY.wrongEmpty }}</h2><p>{{ COPY.wrongEmptyNote }}</p><div class="actions"><button class="btn" @click="$emit('home')">回到今日</button></div></section><p v-if="wrong.total" class="note">{{ COPY.wrongPracticeNote }}</p></main></template>
